const CLIENT_SK = hexToBytes("03".padStart(64, "0"));
const WALLET_SK = hexToBytes("04".padStart(64, "0"));
const OTHER_SK = hexToBytes("05".padStart(64, "0"));
const client = Keys.fromSecretKey(CLIENT_SK);
const wallet = Keys.fromSecretKey(WALLET_SK);
const other = Keys.fromSecretKey(OTHER_SK);
const NONCE = hexToBytes("01".repeat(32));
const IV = hexToBytes("02".repeat(16));
const AUX = new Uint8Array(32);
const CREATED_AT = 1_700_000_000;

function nip44Text(plaintext: string, secret: Uint8Array, peer: string): string {
  const key = nip44.getConversationKey(secret, peer);
  try {
    return nip44.encrypt(plaintext, key, NONCE);
  } finally {
    key.fill(0);
  }
}

function nip04Text(plaintext: string, secret: Uint8Array, peer: string): string {
  const shared = nobleBackend.ecdhX(secret, hexToBytes(peer));
  try {
    const ciphertext = cbc(shared, IV).encrypt(utf8Encoder.encode(plaintext));
    return `${base64.encode(ciphertext)}?iv=${base64.encode(IV)}`;
  } finally {
    shared.fill(0);
  }
}

function signed(secret: Uint8Array, template: EventTemplate): Event {
  return signEvent({ ...template, pubkey: Keys.fromSecretKey(secret).publicKey }, secret, AUX);
}

function requestEvent(plaintext: string, encryption: "nip44_v2" | "nip04"): Event {
  const content =
    encryption === "nip44_v2"
      ? nip44Text(plaintext, CLIENT_SK, wallet.publicKey)
      : nip04Text(plaintext, CLIENT_SK, wallet.publicKey);
  return signed(CLIENT_SK, {
    kind: 23194,
    created_at: CREATED_AT,
    tags: [
      ["p", wallet.publicKey],
      ["encryption", encryption],
      ["expiration", String(CREATED_AT + 30)],
    ],
    content,
  });
}

function responseEvent(
  plaintext: string,
  request: Event,
  encryption: "nip44_v2" | "nip04",
  secret = WALLET_SK,
  mutate?: (template: EventTemplate) => EventTemplate,
): Event {
  const content =
    encryption === "nip44_v2"
      ? nip44Text(plaintext, secret, client.publicKey)
      : nip04Text(plaintext, secret, client.publicKey);
  const base: EventTemplate = {
    kind: 23195,
    created_at: CREATED_AT + 1,
    tags: [
      ["e", request.id],
      ["p", client.publicKey],
    ],
    content,
  };
  return signed(secret, mutate === undefined ? base : mutate(base));
}

